+const navToggle = document.querySelector(".nav-toggle");
+const primaryNav = document.querySelector(".primary-nav");
+const cartLink = document.querySelector(".cart-link");
+const cartCount = document.querySelector(".cart-count");
+const addToCartButtons = document.querySelectorAll(".add-to-cart");
+const countdown = document.querySelector("#deal-countdown");
+const newsletterForm = document.querySelector(".newsletter-form");
+const emailInput = document.querySelector("#email");
+const emailError = document.querySelector("#email-error");
+const formStatus = document.querySelector(".form-status");
+
+let cartItems = 0;
+let remainingSeconds = 6 * 60 * 60;
+
+function closeNavigation() {
+  if (!navToggle || !primaryNav) {
+    return;
+  }
+
+  navToggle.setAttribute("aria-expanded", "false");
+  primaryNav.classList.remove("is-open");
+  document.body.classList.remove("nav-open");
+}
+
+function updateCart(productName, button) {
+  cartItems += 1;
+  cartCount.textContent = String(cartItems);
+  cartLink.setAttribute("aria-label", `Cart, ${cartItems} ${cartItems === 1 ? "item" : "items"}`);
+  button.textContent = "Added";
+  button.classList.add("is-added");
+  button.setAttribute("aria-label", `Added to cart: ${productName}`);
+}
+
+function formatTime(seconds) {
+  const hours = Math.floor(seconds / 3600);
+  const minutes = Math.floor((seconds % 3600) / 60);
+  const secs = seconds % 60;
+
+  return [hours, minutes, secs].map((value) => String(value).padStart(2, "0")).join(":");
+}
+
+function tickCountdown() {
+  if (!countdown) {
+    return;
+  }
+
+  remainingSeconds = remainingSeconds > 0 ? remainingSeconds - 1 : 6 * 60 * 60;
+  countdown.textContent = formatTime(remainingSeconds);
+}
+
+function validateEmail() {
+  if (!emailInput || !emailError) {
+    return false;
+  }
+
+  if (emailInput.validity.valueMissing) {
+    emailError.textContent = "Enter your email address to join the list.";
+    emailInput.setAttribute("aria-invalid", "true");
+    return false;
+  }
+
+  if (emailInput.validity.typeMismatch) {
+    emailError.textContent = "Enter an email address in the format name@example.com.";
+    emailInput.setAttribute("aria-invalid", "true");
+    return false;
+  }
+
+  emailError.textContent = "";
+  emailInput.removeAttribute("aria-invalid");
+  return true;
+}
+
+if (navToggle && primaryNav) {
+  navToggle.addEventListener("click", () => {
+    const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+    navToggle.setAttribute("aria-expanded", String(!isOpen));
+    primaryNav.classList.toggle("is-open", !isOpen);
+    document.body.classList.toggle("nav-open", !isOpen);
+  });
+
+  primaryNav.addEventListener("click", (event) => {
+    if (event.target instanceof HTMLAnchorElement) {
+      closeNavigation();
+    }
